import{_ as t,o as p,c as i,a3 as o}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Research on Pipe Transport Rules","description":"","frontmatter":{"translationSource":{"title":"水管传输规则研究","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=xnJEea1kQCy2zZf8T8Z62O","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/research-on-pipe-transport-rules"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/research-on-pipe-transport-rules"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/research-on-pipe-transport-rules"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/research-on-pipe-transport-rules"}]]},"headers":[],"relativePath":"research-on-pipe-transport-rules.md","filePath":"logistics/src/page-xnJEea1kQCy2zZf8T8Z62O.md"}'),r={name:"research-on-pipe-transport-rules.md"};function a(s,e,n,l,c,d){return p(),i("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><h1 id="research-on-pipe-transport-rules" tabindex="-1">Research on Pipe Transport Rules <a class="header-anchor" href="#research-on-pipe-transport-rules" aria-label="Permalink to &quot;Research on Pipe Transport Rules&quot;">​</a></h1><blockquote><p>Source page ID: <code>xnJEea1kQCy2zZf8T8Z62O</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=xnJEea1kQCy2zZf8T8Z62O" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span id="source-block-pict7gf1bLlBlqhNrk4Yl9"></span></p><h4 id="transport-rules" tabindex="-1">Transport Rules <a class="header-anchor" href="#transport-rules" aria-label="Permalink to &quot;Transport Rules&quot;">​</a></h4><p>Current thinking is that transport follows these rules:</p><p>Equivalent to a belt at four times the speed, with two movements per second. Rendering and operations are aligned to whole seconds, or downloads from and uploads to the server are aligned to seconds. Two liquid types cannot enter the same pipe simultaneously; this is treated as blocking.</p><p>Splitter output lag can also be observed in pipes; it is recorded in <a href="/endfield-skydoc/output-lag-observations-and-mechanism-investigation">Output Lag (“4n Items Stall at Half-Tile Positions”): Observations and Mechanism Investigation</a>.</p><p>Pipes with elevation differences have not yet been investigated.</p><p><span id="source-block-8hw0roUIrVQvGR8LNYpDwH"></span></p><h4 id="droplet-loss" tabindex="-1">Droplet Loss <a class="header-anchor" href="#droplet-loss" aria-label="Permalink to &quot;Droplet Loss&quot;">​</a></h4><p>Reports describe gradually declining liquid quantities in some circulation systems. So far, no loss has been detected except in Fluid Pump/Fluid Supply Unit circulation.</p><p><span id="source-block-ywK4aInuL3po5u1vseysjl"></span></p><h4 id="rendering-rules" tabindex="-1">Rendering Rules <a class="header-anchor" href="#rendering-rules" aria-label="Permalink to &quot;Rendering Rules&quot;">​</a></h4><p>Rendering persists for two seconds. Fluid entering during the first second does not change the displayed fluid; fluid entering during the second does. Reversing the flow immediately resets rendering.</p><p><span id="source-block-JzIMUqaxmK2Qe0ikIis4OA"></span></p><h4 id="conduit-bugs-and-features" tabindex="-1">Conduit Bugs and Features <a class="header-anchor" href="#conduit-bugs-and-features" aria-label="Permalink to &quot;Conduit Bugs and Features&quot;">​</a></h4><p>A bug has been observed where droplets entering both inlets of a dual-inlet conduit simultaneously do not output simultaneously.</p><p>Droplets entering a single-port conduit at 2/s appear to accumulate.</p><p><span id="source-block-1tHPXsSlVEW7krAJi0zuoB"></span></p><h4 id="abnormal-slowdown" tabindex="-1">Abnormal Slowdown <a class="header-anchor" href="#abnormal-slowdown" aria-label="Permalink to &quot;Abnormal Slowdown&quot;">​</a></h4><p>Short pipes reportedly sometimes fail to attain full rate.</p><details><summary>Chat log</summary><p>c  0:39:32</p><p>(<em>^▽^</em>)</p><p>Each pipe unit stores 1 fluid. If too short, pipes sometimes cannot run at full rate.</p><p>@(<em>^▽^</em>) ? Really?</p><p>Orirock  0:40:13</p><p>This problem has always existed.</p><p>c  0:40:33</p><p>?</p><p>c  0:40:53</p><p>But the water entering your machine is still the same, right?</p><p>Orirock  0:41:15</p><p>Pipes that are too short cannot reach full rate.</p><p>c  0:41:31</p><p>But why? I do not understand.</p><p>c  0:41:36</p><p>This is genuinely the first I have heard of it.</p><p>c  0:41:47</p><p>Any research?</p><p>Orirock  0:42:17</p><p>It should count as a bug.</p><p>c  0:42:53</p><p>Any research videos?</p><p>c  0:43:10</p><p>Hmm, a video proving it.</p><p>Orirock  0:44:31</p><p>It is easy to reproduce. I discovered it when it jammed my production line (</p><p>c  0:45:45</p><p>[Endfield: Pipe Length Affects Splitting]</p><p><a href="https://www.bilibili.com/video/BV1FJ546LEg1/?share_source=copy_web&amp;vd_source=d27eb273314c269c7c5618c1541df911" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1FJ546LEg1/?share_source=copy_web&amp;vd_source=d27eb273314c269c7c5618c1541df911</a></p><p>c  0:45:48</p><p>This one?</p><p>c  0:47:53</p><p>So avoid one-tile pipes wherever possible?</p><p>c  0:48:19</p><p>That is awful. Placing a logistics component leaves a one-tile segment, does it not?</p><p>Orirock  0:48:27</p><p>Only full-rate routes need consideration.</p><p>Orirock  0:48:46</p><p>Full-rate short pipes are actually fairly uncommon.</p><p>Orirock  0:49:11</p><p>Also, the problem might not be limited to one tile.</p><p>Orirock  0:49:16</p><p>I have not tested the details.</p><p>Orirock  0:50:41</p><p>c  0:52:12</p><p>An old video.</p><p>c  0:52:18</p><p>Could it be an old problem?</p><p>c  0:52:27</p><p>Sewage used to fluctuate.</p><p>c  0:52:35</p><p>Hmm, but back then people said pipes did not slow down.</p><p>Orirock  0:52:36</p><p>It probably has nothing to do with splitters.</p><p>Orirock  0:52:46</p><p>Just that overly short pipes cannot reach full rate.</p><p>Orirock  0:52:56</p><p>c</p><p>Could it be an old problem?</p><p>@c I encountered it while making Xiranite Jade Gourds.</p><p>Orirock  0:53:03</p><p>I was building a mixed-input Purification Unit.</p><p>Orirock  0:53:26</p><p>Mixing two 1/2 streams in a Purification Unit requires full-rate input.</p><p>Orirock  0:53:34</p><p>My initial version kept jamming.</p><p>Orirock  0:53:45</p><p>Extending the problematic segment fixed it.</p><p>Orirock  0:55:06</p><p>This segment.</p><p>Orirock  0:55:46</p><p>It was originally only three tiles long and jammed.</p><p>Orirock  0:56:23</p><p>Mixed-input Purification Units are extremely sensitive to whether flow is full-rate.</p><p>c  0:56:46</p><p>That is really awful.</p><p>c  0:56:55</p><p>You have to test every segment for full rate.</p><p>c  0:58:13</p><p>I would say Water Treatment Units are the most sensitive to full rate (</p><p>c  0:59:37</p><p>c  0:59:38</p><p>Any explanation?</p><p>Orirock  0:59:38</p><p>A slight slowdown there might only lose a little Cuprium. A mixed-input Purification Unit jams completely after a single frame of slowdown.</p><p>Orirock  1:00:39</p><p>Orirock</p><p>A slight slowdown there might only lose a little Cuprium. A mixed-input Purification Unit jams completely after a single frame of slowdown.</p><p>Both liquids must enter at full rate for alternating production.</p><p>Orirock  1:00:57</p><p>If one arrives late, the other gets in first.</p><p>苍孤狼  1:03:34</p><p>Orirock</p><p>bilibili</p><p>@Orirock Merging pipes should theoretically service inputs round-robin.</p><p>苍孤狼  1:03:51</p><p>The two tanks connected later should not accumulate water.</p><p>c  1:04:26</p><p>That is why the comments say the first conduit he connected is faulty.</p><p>c  1:05:16</p><p>Orirock  1:05:47</p><p>Orirock</p><p>Then why do both Pipe Bridges in my setup slow down?</p><p>苍孤狼  1:06:36</p><p>The 4n, 1 s stall issue</p><p>苍孤狼  1:06:39</p><p>perhaps?</p><p>Orirock  1:06:50</p><p>It stopped slowing after I lengthened it.</p><p>c  1:07:03</p><p>How was it originally connected?</p><p>Orirock  1:08:23</p><p>c  1:10:33</p><p>Hiss.</p><p>c  1:10:38</p><p>Your group has another research topic.</p><p>c  1:12:18</p><p>Could it be a phase issue?</p><p>Orirock  1:12:30</p><p>That seems to explain it.</p><p>Orirock  1:12:38</p><p>Logistics components have lag.</p><p>c  1:12:46</p><p>?</p><p>Orirock  1:13:01</p><p>Liquid cannot enter immediately whenever a pipe has space.</p><p>Orirock  1:13:31</p><p>Also, liquid must traverse the entire pipe length to reach that segment&#39;s outlet.</p><p>Orirock  1:13:52</p><p>That leaves gaps in downstream fluid output.</p></details><p>The cause is thought similar to output lag. Handed over to the output-lag research topic.</p><p><span id="source-block-hWOMdL8nF6l1crvBg94X9L"></span></p><h4 id="abnormal-splitting-with-a-rate-limiter" tabindex="-1">Abnormal Splitting with a Rate Limiter <a class="header-anchor" href="#abnormal-splitting-with-a-rate-limiter" aria-label="Permalink to &quot;Abnormal Splitting with a Rate Limiter&quot;">​</a></h4><p>Reports suggest a splitter placed directly against a rate-limiting control port may fail to reach the port&#39;s configured limit.</p><p>Inspection gives the following example: supply 2 droplets/s continuously for 5s, then 0/s continuously for 5s. Clearly the first 5s can reach the configured rate, but the last 5s cannot. The average flow is below the limit. Add buffering before rate limiting to resolve this. In essence, the buffer is insufficient to support the logic of an idealized logistics system.</p><p><span id="source-block-hrkeHPvDHjYrB6xAUzEgpE"></span></p><h4 id="some-special-factory-input-acceptance-logic" tabindex="-1">Some Special Factory Input Acceptance Logic <a class="header-anchor" href="#some-special-factory-input-acceptance-logic" aria-label="Permalink to &quot;Some Special Factory Input Acceptance Logic&quot;">​</a></h4><p>For pipe inputs</p><p>Gas only: Gas Tank</p><p>Liquid only: Fluid Tank, Reactor Crucible</p><p>Activation material only: the activation ports of Solid-Gas and Fluid-Gas Transmuting Units</p><p>Same liquid only: Conduit, Gas Tank, Fluid Tank, Pipe, Pipe Control Port</p></div>',1)])])}const m=t(r,[["render",a]]);export{h as __pageData,m as default};
